def transform(grid):
    h,w=len(grid),len(grid[0])
    barrier=2
    fixed={(r,c) for r in range(h) for c in range(w) if grid[r][c]==barrier}
    cells={(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (0,barrier)}
    comps=[]
    while cells:
        start=min(cells); color=grid[start[0]][start[1]]
        comp={start}; stack=[start]; cells.remove(start)
        while stack:
            r,c=stack.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in cells and grid[q[0]][q[1]]==color:
                    cells.remove(q); comp.add(q); stack.append(q)
        comps.append((color,comp))
    # Gravity points from the side containing the barrier toward the opposite side.
    upward = all(any(grid[0][c]==barrier for c in range(w)) for _ in [0])
    # barrier occupies top or bottom edge
    upward = any(grid[0][c]==barrier for c in range(w))
    if upward:
        comps.sort(key=lambda x:min(r for r,c in x[1]))
        dr=-1
    else:
        comps.sort(key=lambda x:-max(r for r,c in x[1]))
        dr=1
    occupied=set(fixed)
    result=[[0]*w for _ in range(h)]
    for r,c in fixed: result[r][c]=barrier
    for color,comp in comps:
        shift=0
        while True:
            nxt={(r+dr*(shift+1),c) for r,c in comp}
            if any(r<0 or r>=h or c<0 or c>=w for r,c in nxt) or nxt & occupied:
                break
            shift+=1
        moved={(r+dr*shift,c) for r,c in comp}
        occupied |= moved
        for r,c in moved: result[r][c]=color
    return result

